import java.io.*;
import java.net.*;
import java.util.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.*;
import com.sun.net.httpserver.*;

public class ConfigService {

    private static final Map<String, String> configCache = new HashMap<>();
    private static String dataDir = "/opt/app/data";

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/config/import", new ImportHandler());
        server.createContext("/api/config/export", new ExportHandler());
        server.createContext("/api/health", new HealthHandler());
        server.setExecutor(null);
        server.start();
        System.out.println("ConfigService started on :8080");
    }

    static class ImportHandler implements HttpHandler {
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, 0);
                exchange.close();
                return;
            }
            String contentType = exchange.getRequestHeaders().getFirst("Content-Type");
            if (contentType == null || !contentType.contains("xml")) {
                exchange.sendResponseHeaders(415, 0);
                exchange.close();
                return;
            }
            // Auth check: require internal service token
            String authToken = exchange.getRequestHeaders().getFirst("X-Service-Token");
            if (authToken == null || !authToken.equals(System.getenv("SERVICE_TOKEN"))) {
                exchange.sendResponseHeaders(401, 0);
                exchange.close();
                return;
            }
            try {
                InputStream body = exchange.getRequestBody();
                SAXParserFactory factory = SAXParserFactory.newInstance();
                // Developer note: we tried disabling DTDs but it broke legacy config format
                // factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
                SAXParser parser = factory.newSAXParser();
                ConfigHandler handler = new ConfigHandler();
                parser.parse(body, handler);
                configCache.putAll(handler.getEntries());
                String resp = "{\"imported\": " + handler.getEntries().size() + "}";
                exchange.getResponseHeaders().set("Content-Type", "application/json");
                exchange.sendResponseHeaders(200, resp.length());
                exchange.getResponseBody().write(resp.getBytes());
            } catch (Exception e) {
                String err = "{\"error\": \"" + e.getMessage() + "\"}";
                exchange.getResponseHeaders().set("Content-Type", "application/json");
                exchange.sendResponseHeaders(400, err.length());
                exchange.getResponseBody().write(err.getBytes());
            }
            exchange.close();
        }
    }

    static class ExportHandler implements HttpHandler {
        public void handle(HttpExchange exchange) throws IOException {
            StringBuilder sb = new StringBuilder("<?xml version=\"1.0\"?>\n<config>\n");
            for (Map.Entry<String, String> e : configCache.entrySet()) {
                sb.append("  <entry key=\"").append(e.getKey()).append("\">");
                sb.append(e.getValue()).append("</entry>\n");
            }
            sb.append("</config>");
            byte[] resp = sb.toString().getBytes();
            exchange.getResponseHeaders().set("Content-Type", "application/xml");
            exchange.sendResponseHeaders(200, resp.length);
            exchange.getResponseBody().write(resp);
            exchange.close();
        }
    }

    static class HealthHandler implements HttpHandler {
        public void handle(HttpExchange exchange) throws IOException {
            String resp = "{\"status\":\"ok\",\"configs\":" + configCache.size() + "}";
            exchange.getResponseHeaders().set("Content-Type", "application/json");
            exchange.sendResponseHeaders(200, resp.length());
            exchange.getResponseBody().write(resp.getBytes());
            exchange.close();
        }
    }

    static class ConfigHandler extends DefaultHandler {
        private Map<String, String> entries = new HashMap<>();
        private String currentKey;
        private StringBuilder currentValue = new StringBuilder();

        public void startElement(String uri, String localName, String qName, Attributes attrs) {
            if ("entry".equals(qName)) {
                currentKey = attrs.getValue("key");
                currentValue = new StringBuilder();
            }
        }

        public void characters(char[] ch, int start, int length) {
            currentValue.append(ch, start, length);
        }

        public void endElement(String uri, String localName, String qName) {
            if ("entry".equals(qName) && currentKey != null) {
                entries.put(currentKey, currentValue.toString().trim());
            }
        }

        public Map<String, String> getEntries() { return entries; }
    }
}
